/**
 * Package Purchase Types — Sawaa Dashboard
 *
 * Response shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`).
 *
 * Money is integer halalas everywhere in these shapes (the handler maps
 * `Prisma.Decimal` columns with `Number()` before returning). Query/payload
 * types stay local.
 *
 * Status flow:
 *   ACTIVE     — fresh sale or partially consumed credits
 *   COMPLETED  — every credit bucket has usedQuantity === totalQuantity
 *   REFUNDED   — manual refund by the manager; `refundAmount` populated
 *
 * Note on `method` vs `paymentMethod`: the backend DTO field is `method`
 * (matches `recordPayment` / `Payment.method`), even though the
 * request-response brief sometimes reads `paymentMethod`. The backend
 * schema is authoritative — we POST `{ method }`.
 */

import type { components } from "@/lib/types/api.generated"
import type { PackageDiscountType } from "./package"

type Schemas = components["schemas"]

/* ─── Status / vocabulary (derived) ─── */

export type PackagePurchaseStatus = Schemas["PackagePurchaseStatus"]
export type PackagePurchaseModelVersion = "LEGACY" | "GROUPED_V2"

/**
 * Mirrors the backend `PaymentMethod` enum exposed by `@prisma/client`.
 * The reception sell-package endpoint rejects `ONLINE_CARD` — that flow is
 * reserved for the Moyasar webhook. `COUPON` is reserved too.
 *
 * The dashboard's `record-payment-dialog` types its own narrower union
 * (`CASH | BANK_TRANSFER | MADA | TABBY`); we reuse that list at the UI
 * layer (see sell-package-dialog.tsx) and widen only at the wire boundary.
 */
export type PackagePurchasePaymentMethod = NonNullable<Schemas["CreatePackagePurchaseDto"]["method"]>

/* ─── Entities (derived from OpenAPI) ─── */

/**
 * One credit bucket attached to a PackagePurchase — `(service + employee +
 * duration)` with a frozen unit price (`PackagePurchaseCreditDto`).
 *
 * `remaining = totalQuantity - usedQuantity - reservedQuantity` is
 * pre-computed by the backend so the dashboard's "balance" widget never has
 * to do arithmetic on the client — a reserved session belongs to a
 * booked-but-not-yet-delivered appointment and is not available to book
 * again. The display strings are resolved backend-side.
 */
export type PackageCreditWire = Schemas["PackagePurchaseCreditDto"]

/**
 * Grouped-V2 snapshot fields. The current handler always sets them, but the
 * dashboard has always tolerated their absence on legacy payloads (pre-grouped
 * purchases) and the UI branches on `undefined`; they stay optional here so the
 * rendering logic is unchanged. `modelVersion` rides per-credit on grouped
 * payloads and per-purchase on the list route, so it is optional too.
 */
type OptionalCreditKeys =
  | "purchaseGroupId"
  | "sessionPosition"
  | "groupLabel"
  | "sequenceMode"
  | "dependsOnGroupId"
  | "durationMinsSnapshot"
  | "deliveryTypeSnapshot"
  | "serviceNameSnapshot"
  | "employeeNameSnapshot"
  | "listPriceSnapshot"
  | "netValue"
  | "availability"

/** Dashboard view of one credit bucket: the wire row, with legacy-optional extras. */
export type PackageCredit =
  Omit<PackageCreditWire, OptionalCreditKeys>
  & Partial<Pick<PackageCreditWire, OptionalCreditKeys>>
  & {
    /** Present on grouped/matching payloads; the list route puts it on the purchase. */
    modelVersion?: "LEGACY" | "GROUPED_V2" | null
  }

/** One credit's eligibility snapshot (`PackagePurchaseCreditConstraintDto`). */
export type PackageCreditConstraint = Schemas["PackagePurchaseCreditConstraintDto"]

/** Eligibility rule dimension (mirrors the backend `PackageConstraintDimension`). */
export type CreditConstraintDimension = PackageCreditConstraint["dimension"]

/** Eligibility rule mode (mirrors the backend `PackageConstraintMode`). */
export type CreditConstraintMode = PackageCreditConstraint["mode"]

/** Backend-computed availability (`PackagePurchaseCreditAvailabilityDto`). */
export type PackageCreditAvailability = Schemas["PackagePurchaseCreditAvailabilityDto"]

/**
 * A client's package purchase with its credits (`PackagePurchaseListRowDto`).
 * `subtotalSnapshot` / `discountSnapshot` / `amountPaid` are the frozen prices
 * at sale time — they may differ from the current `SessionPackage.finalPrice`
 * if the catalog has been edited since the sale.
 */
export type PackagePurchaseWire = Schemas["PackagePurchaseListRowDto"]

/**
 * Optional purchase fields: the family/offer snapshot columns only exist on
 * purchases made from a family, and `vatAmount` / `totalCharged` / grouped
 * metadata were added after the first sales. Older payloads omit them, and the
 * UI already guards each one.
 */
type OptionalPurchaseKeys =
  | "invoiceId"
  | "branchId"
  | "packageFamilyId"
  | "offerSnapshot"
  | "familyId"
  | "familyNameAr"
  | "familyNameEn"
  | "optionNameAr"
  | "optionNameEn"
  | "sessionCount"
  | "vatAmount"
  | "totalCharged"
  | "modelVersion"

/** Dashboard view of a client package purchase: the wire row, with legacy-optional extras. */
export type PackagePurchase =
  Omit<PackagePurchaseWire, OptionalPurchaseKeys | "credits">
  & Partial<Pick<PackagePurchaseWire, OptionalPurchaseKeys>>
  & {
    /** Credits carry the dashboard view above (legacy-optional extras). */
    credits: PackageCredit[]
    /** Purchase model version when the payload carries it. */
    modelVersion?: "LEGACY" | "GROUPED_V2"
  }

/** `POST /dashboard/finance/package-purchases/:purchaseId/refund` (`PackagePurchaseRefundResponseDto`). */
export type RefundPackagePurchaseResult = Schemas["PackagePurchaseRefundResponseDto"]

/* ─── Write side (mirror the request DTOs) ─── */

/**
 * Body of `POST /dashboard/finance/package-purchases` (`CreatePackagePurchaseDto`).
 * The dashboard sells at the desk via manual payment — `ONLINE_CARD` is
 * rejected server-side and `COUPON` is not wired at this endpoint.
 */
export type CreatePackagePurchasePayload = Schemas["CreatePackagePurchaseDto"]

/**
 * Response of `POST /dashboard/finance/package-purchases`.
 *
 * DEFERRED: the handler returns an untyped four-branch union with index
 * signatures (`[x: string]: unknown`) and per-branch credit shapes, so it has
 * no exact response schema yet. This local shape documents only the four keys
 * the dashboard actually reads; it is NOT derived from the snapshot.
 */
export interface CreatePackagePurchaseResult {
  purchase: PackagePurchase
  invoiceId: string
  paymentId: string | null
  credits: Array<{
    serviceId: string | null
    employeeId: string | null
    durationOptionId: string | null
    /** Integer halalas. */
    unitPriceSnapshot: number
    totalQuantity: number
    usedQuantity: number
    /** Always 0 at creation — no booking exists yet to reserve a slot. */
    reservedQuantity: number
  }>
}

/* ─── Query ─── */

export interface ClientPackagePurchasesQuery {
  status?: PackagePurchaseStatus
}

/**
 * Re-export of the package discount type so consumers that import
 * `package-purchase.ts` do not also need to pull `./package` for the
 * `PackageDiscountType` they reference in the price preview.
 */
export type { PackageDiscountType }
